mapper.sql:
FROM tb_show s
INNER JOIN tb_performance p ON p.id = s.performance_id
INNER JOIN tb_venue v ON v.id = s.venue_id
WHERE 1 = 1


    AND (
        p.title LIKE CONCAT('%', #{keyword}, '%')
        OR p.artist_name LIKE CONCAT('%', #{keyword}, '%')
        OR v.name LIKE CONCAT('%', #{keyword}, '%')
    )


    AND v.city = #{city}


    AND p.artist_id = #{artistId}


    AND s.start_time >= #{timeStart}


    AND s.start_time < #{timeEnd}


    AND  >= #{priceMin}


    AND  <= #{priceMax}



    AND EXISTS (
        SELECT 1 FROM tb_ticket_type tt
        WHERE tt.show_id = s.id
          AND tt.status = 1
          AND tt.left_stock > 0
          AND tt.sale_start_time <= NOW()
          AND tt.sale_end_time >= NOW()
    )

mapper.select:
SELECT CAST(a.id AS CHAR) AS id, a.name, a.avatar, a.type, a.city, a.follow_count AS followCount FROM tb_artist a WHERE 1 = 1
AND a.name LIKE CONCAT('%', #{keyword}, '%')
ORDER BY a.follow_count DESC LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM tb_venue v WHERE 1 = 1
AND v.name LIKE CONCAT('%', #{keyword}, '%')
AND v.city = #{city}

SELECT CAST(v.id AS CHAR) AS id, v.name, v.city, v.address FROM tb_venue v WHERE 1 = 1
AND v.name LIKE CONCAT('%', #{keyword}, '%')
AND v.city = #{city}
ORDER BY v.id DESC LIMIT #{offset}, #{size}
